 */
const classifyJsCallout = (lines: string[]): Segment | undefined => {
  if (lines.length !== 3 || lines[0] !== JS_CALLOUT_MARKER || lines[1] !== "> [!TIP]")
    return undefined;
  const match = CALLOUT_LINE_RE.exec(lines[2]);
  if (!match) return undefined;
  const [, label, note] = match;
  return { kind: "callout", marker: lines[0], alertLine: lines[1], label, note };
};

/** Classify a run of consecutive non-blank, non-fenced lines. */
const classifyBlock = (lines: string[]): Segment => {
  const text = lines.join("\n");
  const first = lines[0];
  if (first === GENERATED_VALUES_MARKER)
    return { kind: "prose", text: lines.slice(1).join("\n"), generatedValues: true };

  // Table: header row + separator. Only translate cells when the grid rebuilds exactly to the source,
  // so anything with unexpected spacing/escaping is preserved whole rather than silently reformatted.
  if (lines.length >= 2 && first.trimStart().startsWith("|") && isSeparatorRow(lines[1])) {
    const rows = lines.map(parseRow);
    if (rows.map(rebuildRow).join("\n") === text) {
      const descCols = rows[0]
        .map((header, index) => (/^(description|summary)$/i.test(header) ? index : -1))
        .filter((index) => index >= 0);
      return { kind: "table", rows, rawRows: lines, headerRow: 0, separatorRow: 1, descCols };
    }
    return { kind: "preserve", text };
  }

  const callout = classifyJsCallout(lines);
  if (callout) return callout;

  if (text.includes('class="pantoken-a11y-table"'))
    return { kind: "audit", body: segmentDemoHtml(text) };

  // Headings and stability-badge pills → deterministic glossary. The glossary no-ops on identifiers
  // (`### options?`) and on words it doesn't know, so routing every heading here is safe.
  if (/^#{1,6}\s/.test(first)) return { kind: "glossary", text };
  if (first.trimStart().startsWith("<")) {
    return { kind: text.includes("pantoken-doc-tag") ? "glossary" : "preserve", text };
  }

  // Signatures/blockquotes, breadcrumbs, and lines that are only links/code/type expressions.
  if (first.trimStart().startsWith(">")) return { kind: "preserve", text };
  if (isBreadcrumb(first)) return { kind: "preserve", text };
  if (isFlagOnly(text)) return { kind: "preserve", text };
  if (!hasProseWords(text)) return { kind: "preserve", text };

  return { kind: "prose", text };
};

/**
 * A leading closed `---` YAML frontmatter block as a preserve segment plus the index just past it,
 * or `null` when `lines` doesn't open with one. (Generated API pages don't emit it today, but be safe.)
 */
const takeFrontmatter = (lines: string[]): { segment: Segment; nextIndex: number } | null => {
  if (lines[0] !== "---") return null;
  let end = 1;
  while (end < lines.length && lines[end] !== "---") end += 1;
  if (end >= lines.length) return null;
  return {

  return {
    segment: { kind: "preserve", text: lines.slice(0, end + 1).join("\n") },
    nextIndex: end + 1,
  };
};

/** Index just past a fenced code block opening at `start` (includes the closing fence). */
const scanFence = (lines: string[], start: number): number => {
  let index = start + 1;
  while (index < lines.length && !FENCE.test(lines[index])) index += 1;
  if (index < lines.length) index += 1; // include the closing fence
  return index;
};

/** Index just past a run of blank lines starting at `start`. */
const scanBlankRun = (lines: string[], start: number): number => {
  let index = start;
  while (index < lines.length && lines[index].trim() === "") index += 1;
  return index;
};

/** Split markdown into ordered, lossless segments. */
export function segmentMarkdown(md: string, options: { scope?: string } = {}): Segment[] {
  const lines = md.split("\n");
  const segments: Segment[] = [];
  let index = 0;

  const frontmatter = takeFrontmatter(lines);
  if (frontmatter) {
    segments.push(frontmatter.segment);
    index = frontmatter.nextIndex;
  }

  let block: string[] = [];
  const flush = (): void => {
    if (block.length > 0) {
      const segment = classifyBlock(block);
      if (segment.kind === "callout" || (segment.kind === "prose" && segment.generatedValues))
        segment.scope = options.scope;
      segments.push(segment);
      block = [];
    }
  };

  while (index < lines.length) {
    const line = lines[index];

    if (FENCE.test(line)) {
      flush();
      const start = index;
      index = scanFence(lines, start);
      const hasClosingFence = index > start + 1 && FENCE.test(lines[index - 1]);
      if (HTML_FENCE.test(line) && hasClosingFence) {
        segments.push({
          kind: "html",
          opening: lines[start],
          body: segmentDemoHtml(lines.slice(start + 1, index - 1).join("\n")),
          closing: lines[index - 1],
        });
      } else if (PROMPT_FENCE.test(line) && hasClosingFence) {
        segments.push({
          kind: "prompt",
          opening: lines[start],
          body: lines.slice(start + 1, index - 1).join("\n"),
          closing: lines[index - 1],
        });
      } else {
        segments.push({ kind: "preserve", text: lines.slice(start, index).join("\n") });
      }
      continue;
    }

    if (line.trim() === "") {
      flush();
      const start = index;
      index = scanBlankRun(lines, start);
      segments.push({ kind: "preserve", text: lines.slice(start, index).join("\n") });
      continue;
    }

    if (isFlagOnly(line.trim())) {
      flush();
      segments.push({ kind: "preserve", text: line });
      index += 1;
      continue;
    }

    block.push(line);
    index += 1;
  }
  flush();

  return segments;
}

/** Translatable header labels + Description-cell units from one table segment, in document order. */
const collectTableUnits = (segment: Extract<Segment, { kind: "table" }>): TranslatableUnit[] => {
  const units: TranslatableUnit[] = [];
  for (const header of segment.rows[segment.headerRow]) {
    if (header !== "") units.push({ text: header, kind: "glossary" });
  }
  for (let row = 0; row < segment.rows.length; row += 1) {
    if (row === segment.headerRow || row === segment.separatorRow) continue;
    for (const col of segment.descCols) {
      const cell = segment.rows[row][col];
      if (cell !== undefined && isTranslatableCell(cell)) {
        units.push({ text: cell, kind: cellKind(cell) });
      }
    }
  }
  return units;
};

/** Every translatable unit across the segments, in document order (callers dedupe by content). */
export function collectUnits(segments: readonly Segment[]): TranslatableUnit[] {
  const units: TranslatableUnit[] = [];
  for (const segment of segments) {
    if (segment.kind === "glossary" || segment.kind === "prose") {
      units.push({
        text:
          segment.kind === "prose" && segment.generatedValues
            ? scopeGeneratedMarkdown(generatedMarkdown(segment.text), segment.scope).template
            : segment.text,
        kind: segment.kind,
      });
      continue;
    }
    if (segment.kind === "prompt") {
      units.push({ text: segment.body, kind: "prose" });
      continue;
    }
    if (segment.kind === "html") {
      units.push(
        ...collectDemoUnits(segment.body).map((text) => ({
          text,
          kind: "prose" as const,
          translateCodeShaped: true,
        })),
      );
      continue;
    }
    if (segment.kind === "table") {
      units.push(...collectTableUnits(segment));
      continue;
    }
    if (segment.kind === "audit") {
      units.push(
        ...collectDemoUnits(segment.body).map((text) => ({ text, kind: "prose" as const })),
      );
      continue;
    }
    if (segment.kind === "callout") {
      units.push(
        { text: segment.label, kind: "glossary" },
        {
          text: scopeGeneratedMarkdown(generatedMarkdown(segment.note), segment.scope).template,
          kind: "prose",
        },
      );
    }
  }
  return units;
}

/** Rebuild markdown from segments, resolving each translatable unit through `resolve`. */
export function reassemble(segments: readonly Segment[], resolve: Resolve): string {
  return segments.map((segment) => renderSegment(segment, resolve)).join("\n");
}

const resolveGenerated = (text: string, resolve: Resolve, scope?: string): string => {
  const generated = scopeGeneratedMarkdown(generatedMarkdown(text), scope);
  return restoreGeneratedMarkdown(resolve(generated.template, "prose"), generated);
};

const renderSegment = (segment: Segment, resolve: Resolve): string => {
  switch (segment.kind) {
    case "preserve":
      return segment.text;
    case "prompt":
      return [segment.opening, resolve(segment.body, "prose"), segment.closing].join("\n");
    case "html":
      return [
        segment.opening,
        reassembleDemoHtml(segment.body, (text) => resolve(text, "prose")),
        segment.closing,
      ].join("\n");
    case "audit":
      return reassembleDemoHtml(segment.body, (text) => resolve(text, "prose"));
    case "glossary":
      return resolve(segment.text, segment.kind);
    case "prose":
      return segment.generatedValues
        ? `${GENERATED_VALUES_MARKER}\n${resolveGenerated(segment.text, resolve, segment.scope)}`
        : resolve(segment.text, segment.kind);
    case "table":
      return renderTable(segment, resolve);
    case "callout":
      return [
        segment.marker,
        segment.alertLine,
        `> **${resolve(segment.label, "glossary")}** — ${resolveGenerated(segment.note, resolve, segment.scope)}`,
      ].join("\n");
  }
};

const renderTable = (segment: Extract<Segment, { kind: "table" }>, resolve: Resolve): string =>
  segment.rows
    .map((cells, row) => {
      const rendered = cells.map((cell, col) => {
        if (row === segment.separatorRow) return cell;
        if (row === segment.headerRow) return cell === "" ? cell : resolve(cell, "glossary");
        if (segment.descCols.includes(col) && isTranslatableCell(cell)) {
          return resolve(cell, cellKind(cell));
        }
        return cell;
      });
      return rebuildRowPreservingSpacing(segment.rawRows[row], rendered);
    })
    .join("\n");

/**
 * The real `docs.guides` extractor — Phase 2 of the localization-engine plan
 * (`.claude/plans/localization-engine.md`). Promotes the offset-splice technique proven in the
 * Phase 0 spike (`docs/scripts/offset-splice-spike.ts`) into the engine.
 *
 * Scope for this increment: only prose `text` mdast nodes are extracted (paragraphs, headings, list
 * items, table cells, link text). Code fences (`html`/`jsx`/`mermaid`/etc.) stay preserved verbatim —
 * translating prose INSIDE a fence needs the `embedded:html`/`embedded:shell`/`embedded:mermaid`
 * sub-extractors, which are real Phase 4 production work, not this MVP.
 *
 * @module
 */
import { globSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { unified } from "unified";
import remarkGfm from "remark-gfm";
import remarkParse from "remark-parse";
import { visit } from "unist-util-visit";
import type { CatalogUnit } from "./units.ts";

/** A translatable leaf: an absolute `[start, end)` byte range into the source string. */
export interface ProseRange {
  start: number;
  end: number;
  text: string;
}

/** One extracted unit for a POT template: the source text plus where it came from. */
export interface ExtractedUnit extends CatalogUnit {
  msgid: string;
  /** `"<repo-relative path>:<1-indexed line>"`. */
}

const parser = unified().use(remarkParse).use(remarkGfm);

interface MdastNode {
  type: string;
  position?: { start: { line?: number; offset?: number }; end: { offset?: number } };
}

const FRONTMATTER_KEYS = new Set(["text", "tagline", "title", "details"]);
const LINK_KEY = new Set(["link"]);

interface FrontmatterField {
  prefix: string;
  key: string;
  separator: string;
  value: string;
}

function parseFrontmatterField(
  line: string,
  allowedKeys: ReadonlySet<string> = FRONTMATTER_KEYS,
): FrontmatterField | undefined {
  const colon = line.indexOf(":");
  if (colon < 0) return undefined;
  const before = line.slice(0, colon);
  const trimmed = before.trim();
  const key = trimmed.startsWith("-") ? trimmed.slice(1).trim() : trimmed;
  if (!allowedKeys.has(key)) return undefined;
  const keyStart = before.lastIndexOf(key);
  const afterColon = line.slice(colon + 1);
  const value = afterColon.trimStart();
  return {
    prefix: before.slice(0, keyStart),
    key,
    separator: afterColon.slice(0, afterColon.length - value.length),
    value,
  };
}

function replaceDelimited(
  source: string,
  delimiter: string,
  replacementDelimiter: string,
  restrictContent?: (content: string) => boolean,
): string {
  let out = "";
  let cursor = 0;
  while (cursor < source.length) {
    const start = source.indexOf(delimiter, cursor);
    if (start < 0) return out + source.slice(cursor);
    out += source.slice(cursor, start);
    const contentStart = start + delimiter.length;
    const end = source.indexOf(delimiter, contentStart);
    if (end < 0) return out + source.slice(start);
    const content = source.slice(contentStart, end);
    if (restrictContent && !restrictContent(content)) {
      out += delimiter;
      cursor = contentStart;
      continue;
    }
    out += `${replacementDelimiter}${content}${replacementDelimiter}`;
    cursor = end + delimiter.length;
  }
  return out;
}

const normalizeGraves = (value: string): string =>
  replaceDelimited(value, "&grave;", "`", (content) => !content.includes("&"));

const escapeGraves = (value: string): string => replaceDelimited(value, "`", "&grave;");

const escapeFrontmatterValue = (value: string): string =>
  escapeGraves(value).replace(/:(\s|$)/gu, "&colon;$1");

/** Collect every non-blank prose `text` node's absolute range — never a `code`/`inlineCode` leaf. */
export function collectProseRanges(source: string): ProseRange[] {
  const tree = parser.parse(source);
  const ranges: ProseRange[] = [];
  visit(tree, (rawNode) => {
    const node = rawNode as MdastNode;
    if (node.type !== "text") return;
    const start = node.position?.start.offset;
    const end = node.position?.end.offset;
    if (start === undefined || end === undefined) return;
    const text = source.slice(start, end);
    if (text.trim() === "") return;
    ranges.push({ start, end, text });
  });
  return ranges;
}

/** Extract POT-ready units from one file's already-read `source`. */
export function extractFileUnits(source: string, filePath: string): ExtractedUnit[] {
  return collectProseRanges(source).map((range) => {
    const line = source.slice(0, range.start).split("\n").length;
    return {
      msgid: range.text,
      reference: `${filePath}:${String(line)}`,
      translate: "always",
    };
  });
}

/** Every `docs.guides` file under `docsRoot`'s `guide/` subdirectory plus `compatibility.md`, sorted, relative to `docsRoot`. */
export function listGuideFiles(docsRoot: string): string[] {
  const guideFiles = globSync("guide/**/*.md", { cwd: docsRoot });
  const compatibilityFile = "compatibility.md";
  const files = [...new Set([...guideFiles, compatibilityFile])];
  return files.sort();
}

/** Extract every `docs.guides` file under `docsRoot` (its `guide/` subdirectory, recursively). */
export function extractGuideSpace(docsRoot: string): ExtractedUnit[] {
  return listGuideFiles(docsRoot).flatMap((file) =>
    extractFileUnits(readFileSync(join(docsRoot, file), "utf8"), file),
  );
}

/** Extract visible VitePress home-page frontmatter values while leaving routes and structure alone. */
export function extractFrontmatterUnits(source: string, filePath: string): ExtractedUnit[] {
  const lines = source.split("\n");
  if (lines[0]?.trim() !== "---") return [];
  const end = lines.findIndex((line, index) => index > 0 && line.trim() === "---");
  if (end === -1) return [];
  const units: ExtractedUnit[] = [];
  for (let index = 1; index < end; index += 1) {
    const field = parseFrontmatterField(lines[index]);
    const value = field?.value;
    if (!value) continue;
    units.push({
      msgid: normalizeGraves(value),
      reference: `${filePath}:${String(index + 1)}`,
      translate: "always",
    });
  }
  return units;
}

/** Render translated home-page frontmatter values without reserializing YAML. */
export function renderFrontmatterFile(
  source: string,
  resolve: (text: string) => string,
  locale?: string,
): string {
  const lines = source.split("\n");
  if (lines[0]?.trim() !== "---") return source;
  const end = lines.findIndex((line, index) => index > 0 && line.trim() === "---");
  if (end === -1) return source;
  for (let index = 1; index < end; index += 1) {
    const line = lines[index];
    const colon = line.indexOf(":");
    const before = colon < 0 ? "" : line.slice(0, colon).trim();
    const link = before === "link" ? parseFrontmatterField(line, LINK_KEY) : undefined;
    if (link && locale && link.value.startsWith("/") && !link.value.startsWith(`/${locale}/`)) {
      lines[index] = `${link.prefix}link:${link.separator}/${locale}${link.value}`;
      continue;
    }
    const field = parseFrontmatterField(line);
    if (!field?.value) continue;
    const translated = escapeFrontmatterValue(resolve(normalizeGraves(field.value)));
    lines[index] = `${field.prefix}${field.key}:${field.separator}${translated}`;
  }
  return lines.join("\n");
}

/**
 * Splice `resolve`d prose back into `source` — descends by offset so earlier splices don't shift
 * later ones. `resolve` returning its input verbatim (the identity function) round-trips exactly.
 */
export function renderRanges(
  source: string,
  ranges: readonly ProseRange[],
  resolve: (text: string) => string,
): string {
  const orderedRanges = [...ranges].sort((a, b) => b.start - a.start);
  let out = source;
  for (const range of orderedRanges) {
    out = out.slice(0, range.start) + resolve(range.text) + out.slice(range.end);
  }
  return out;
}

/** Splice resolved prose units back into a source file without reserializing its syntax tree. */
export function renderFile(source: string, resolve: (text: string) => string): string {
  return renderRanges(source, collectProseRanges(source), resolve);
}

